import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper enters shipping options. No shipping options are part of the event payload.
*/
export type CheckoutShippingOptions = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutShippingOptionsBuilder {

    private checkoutShippingOptions: CheckoutShippingOptions = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutShippingOptionsBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutShippingOptionsBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutShippingOptionsBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutShippingOptionsBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutShippingOptions {
        if(this.cart) {
            this.checkoutShippingOptions.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.checkoutShippingOptions.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutShippingOptions.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutShippingOptions.events.push(this.partyIdentification);
        }

        return this.checkoutShippingOptions;
    }
}
